        }
        break;
      case 'ArrowDown':
        for (let r = rowIndex + 1; r < map.rows.length && !nextSeat; r++) {
          nextSeat = this.selectableSeatAt(map.rows[r], current.column);
        }
        break;
      case 'ArrowUp':
        for (let r = rowIndex - 1; r >= 0 && !nextSeat; r--) {
